                this.init();
            }

            init() {
                this.setupIntersectionObserver();
                this.setupKeyboardNav();
                this.setupProgressBar();
                this.setupNavDots();
                this.animateSlideNumbers();
            }

            setupIntersectionObserver() {
                const options = {
                    root: null,
                    rootMargin: '0px',
                    threshold: 0.5
                };

                const observer = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            entry.target.classList.add('visible');
                            const slideIndex = Array.from(this.slides).indexOf(entry.target);
                            this.currentSlide = slideIndex;
                            this.updateProgress();
                            this.updateNavDots();
                            this.updateSlideCounter();
                        }
                    });
                }, options);

                this.slides.forEach(slide => observer.observe(slide));
            }

            setupKeyboardNav() {
                document.addEventListener('keydown', (e) => {
                    switch(e.key) {
                        case 'ArrowDown':
                        case 'ArrowRight':
                        case ' ':
                        case 'PageDown':
                            e.preventDefault();
                            this.nextSlide();
                            break;
                        case 'ArrowUp':
                        case 'ArrowLeft':
                        case 'PageUp':
                            e.preventDefault();
                            this.prevSlide();
                            break;
                        case 'Home':
                            e.preventDefault();
                            this.goToSlide(0);
                            break;
                        case 'End':
                            e.preventDefault();
                            this.goToSlide(this.totalSlides - 1);
                            break;
                    }
                });
            }

            setupProgressBar() {
                this.updateProgress();
            }

            setupNavDots() {
                this.navDots.innerHTML = '';
                this.slides.forEach((_, index) => {
                    const dot = document.createElement('div');
                    dot.className = 'nav-dot' + (index === 0 ? ' active' : '');
                    dot.addEventListener('click', () => this.goToSlide(index));
                    this.navDots.appendChild(dot);
                });
            }

            updateProgress() {
                const progress = ((this.currentSlide + 1) / this.totalSlides) * 100;
                this.progressBar.style.width = progress + '%';
            }

            updateNavDots() {
                const dots = this.navDots.querySelectorAll('.nav-dot');
                dots.forEach((dot, index) => {
                    dot.classList.toggle('active', index === this.currentSlide);
                });
            }

            updateSlideCounter() {
                this.slideCounter.textContent = this.currentSlide + 1;
            }

            nextSlide() {
                if (this.currentSlide < this.totalSlides - 1) {
                    this.goToSlide(this.currentSlide + 1);
                }
            }

            prevSlide() {
                if (this.currentSlide > 0) {
                    this.goToSlide(this.currentSlide - 1);
                }
            }

            goToSlide(index) {
                this.slides[index].scrollIntoView({ behavior: 'smooth' });
            }

            animateSlideNumbers() {
                // Add visible class to first slide initially
                setTimeout(() => {
                    this.slides[0].classList.add('visible');
                }, 100);
            }
        }

        // Initialize presentation
        document.addEventListener('DOMContentLoaded', () => {
            new SlidePresentation();
        });
    </script>
